import java.util.Scanner;

public class Main {
    static long[] f = new long[181];
    static long n;
    static long minCost;

    static long getAbs(long x) {
        return x < 0 ? -x : x;
    }

    static void dfs(int level, long cost) {
        if (n == 0) {
            if (cost < minCost) {
                minCost = cost;
            }
            return;
        }
        if (level == 0) return;

        for (int i = -10; i <= 10; ++i) {
            long diff = i * f[level];
            if (n + diff > 0) {
                n += diff;
                dfs(level - 1, cost + getAbs(i) * level);
                n -= diff;
                break;
            }
        }
        for (int i = -10; i <= 10; ++i) {
            long diff = i * f[level];
            if (n + diff == 0) {
                n += diff;
                dfs(level - 1, cost + getAbs(i) * level);
                n -= diff;
                break;
            }
        }
        for (int i = 10; i >= -10; --i) {
            long diff = i * f[level];
            if (n + diff < 0) {
                n += diff;
                dfs(level - 1, cost + getAbs(i) * level);
                n -= diff;
                break;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        f[1] = 1;
        for (int i = 2; i <= 16; ++i) {
            f[i] = f[i - 1] * 10 + 1;
        }
        minCost = Long.MAX_VALUE;
        dfs(16, 0);
        System.out.println(minCost);
        sc.close();
    }
}
